func TestMeteredBillsUsageInArrears(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
		t.Fatalf("a metered plan was invoiced in advance: %+v", invs)
	}
	start, end := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	for _, u := range []struct {
		q  int64
		at time.Time
	}{{100, start}, {250, start.Add(48 * time.Hour)}, {7, end}} {
		if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || len(invs[0].Lines) != 1 || invs[0].Lines[0].Quantity != 350 || !invs[0].PeriodEnd.Equal(end) {
		t.Fatalf("invoices = %+v (usage at the period's end belongs to the next period)", invs)
	}
}
func TestPlans(t *testing.T) {
	e := apitest.New(t)
	var p struct {
		store.Plan
		Price          string `json:"price"`
		PriceFormatted string `json:"price_formatted"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Team", "currency": "USD", "price": "12.50", "interval": "month"}, &p)
	if p.UnitAmount != 1250 || p.Price != "12.50" || p.PriceFormatted != "$12.50" || !p.Active || p.UsageType != store.Licensed {
		t.Fatalf("plan = %+v", p)
	}
	for _, bad := range []map[string]any{
		{"name": "X", "currency": "USD", "price": "abc", "interval": "month"},
		{"name": "X", "currency": "USD", "price": "-1", "interval": "month"},
	} {
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, bad); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_amount" {
			t.Fatalf("%v: %s", bad, r)
		}
	}
	if r := e.Do("POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "X", "currency": "USD", "price": "1", "interval": "week"}); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("weekly: %s", r)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/plans/"+p.ID, e.Acme.Key, map[string]any{"active": false}, &p)
	if p.Active {
		t.Fatal("still active")
	}
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	if r := e.Do("POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "plan_inactive" {
		t.Fatalf("subscribe to an inactive plan: %s", r)
	}
}

