		name     string
		mode     store.TiersMode
		quantity int64
		want     int64
	}{
		{"graduated, no usage", store.Graduated, 0, 0},
		{"graduated, inside the first tier", store.Graduated, 4, 4*500 + 1000},
		{"graduated, up to the first tier's limit", store.Graduated, 10, 10*500 + 1000},
		{"graduated, into the second tier", store.Graduated, 11, 10*500 + 1000 + 1*300 + 1000},
		{"graduated, up to the second tier's limit", store.Graduated, 100, 10*500 + 1000 + 90*300 + 1000},
		{"graduated, into the unlimited tier", store.Graduated, 105, 10*500 + 1000 + 90*300 + 1000 + 5*100 + 5000},
		{"volume, no usage", store.Volume, 0, 0},
		{"volume, inside the first tier", store.Volume, 4, 4*500 + 1000},
		{"volume, up to the first tier's limit", store.Volume, 10, 10*500 + 1000},
