func TestPlanTiers(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	upTo := func(n int64) *int64 { return &n }
	metered := func(mode TiersMode, tiers ...Tier) Plan {
		return Plan{OrgID: a.ID, Name: "Calls", Currency: money.USD, Interval: Monthly, UsageType: Metered, TiersMode: mode, Tiers: tiers}
	}
	good := []Tier{{UpTo: upTo(10), UnitAmount: 5}, {UnitAmount: 3, FlatAmount: 100}}
	p, err := s.CreatePlan(metered(Graduated, good...), t0)
	if err != nil || p.TiersMode != Graduated || len(p.Tiers) != 2 || p.UnitAmount != 0 {
		t.Fatalf("CreatePlan = %+v, %v", p, err)
	}
	for name, bad := range map[string]Plan{
		"no mode":         metered("", good...),
		"unknown mode":    metered("stairs", good...),
		"no tiers":        metered(Volume),
		"not ascending":   metered(Volume, Tier{UpTo: upTo(10), UnitAmount: 1}, Tier{UpTo: upTo(10), UnitAmount: 1}, Tier{UnitAmount: 1}),
		"zero up_to":      metered(Volume, Tier{UpTo: upTo(0), UnitAmount: 1}, Tier{UnitAmount: 1}),
		"last has up_to":  metered(Volume, Tier{UpTo: upTo(10), UnitAmount: 1}),
		"middle unlimited": metered(Volume, Tier{UnitAmount: 1}, Tier{UnitAmount: 1}),
		"negative amount": metered(Volume, Tier{UnitAmount: -1}),
		"negative flat":   metered(Volume, Tier{FlatAmount: -1}),
	} {
		if _, err := s.CreatePlan(bad, t0); !errors.Is(err, ErrInvalidTiers) {
			t.Errorf("%s: CreatePlan err = %v, want ErrInvalidTiers", name, err)
		}
	}
	licensed := Plan{OrgID: a.ID, Name: "Seats", Currency: money.USD, UnitAmount: 100, Interval: Monthly, Tiers: good, TiersMode: Graduated}
	if _, err := s.CreatePlan(licensed, t0); !errors.Is(err, ErrInvalidTiers) {
		t.Fatalf("tiers on a licensed plan: %v", err)
	}
	if up, err := s.UpdatePlan(a.ID, p.ID, func(p *Plan) error { p.Tiers = nil; p.TiersMode = Volume; return nil }); err != nil || up.TiersMode != Graduated || len(up.Tiers) != 2 {
		t.Fatalf("UpdatePlan = %+v, %v (the tiers must not change)", up, err)
	}
}

