func TestTieredAmount(t *testing.T) {
	upTo := func(n int64) *int64 { return &n }
	tiers := []store.Tier{
		{UpTo: upTo(10), UnitAmount: 500},
		{UpTo: upTo(100), UnitAmount: 300, FlatAmount: 1000},
