		name     string
		mode     store.TiersMode
		quantity int64
		want     int64
	}{
		{"graduated, no usage", store.Graduated, 0, 0},
		{"graduated, inside the first tier", store.Graduated, 4, 4*500 + 1000},
		{"graduated, up to the first tier's limit", store.Graduated, 10, 10*500 + 1000},
		{"graduated, into the second tier", store.Graduated, 11, 10*500 + 1000 + 1*300 + 1000},
